// Üretilen dosya: tool/ozgun/uret.py. Kimya · Mol kavramı ve kimyasal hesaplamalar (zor).
const ozChemistry9Zor = <(String, String, List<String>, String)>[
  ('2019\'da Avogadro sabiti tam bir sayıya sabitlendikten sonra 12 g saf karbon-12 örneği için hangisi doğrudur?', 'Artık tanım gereği tam 1 mol değildir, ama çok yakındır.', ['Tanım gereği tam olarak 1 mol olmaya devam eder.', 'Yaklaşık 0,5 mol karbon atomu içerir.', 'Atom kütlesi değiştiği için 2 mol karbon içerir.'], 'Yeni tanımda mol, Avogadro sabitinden türetilir. Karbon-12\'nin mol kütlesi artık deneysel bir değerdir ve 12 g/mol\'e son derece yakındır ama tanımsal olarak tam değildir.'),
  ('1865\'te bir gazın birim hacmindeki molekül sayısını ilk kez kestirerek moleküllerin büyüklüğüne ilişkin sayısal bir değer veren Avusturyalı bilim insanı kimdir?', 'Josef Loschmidt', ['Ludwig Boltzmann', 'Johann Balmer', 'Christian Doppler'], 'Josef Loschmidt 1865\'te kinetik kuramdan yararlanarak birim hacimdeki gaz molekülü sayısını kestirmiştir; bu sayı onun adıyla da anılır.'),
  ('Avogadro sabitini çok yüksek doğrulukla belirlemek için yürütülen uluslararası projede, atomları sayılan neredeyse kusursuz küreler hangi maddeden yapılmıştır?', 'Silisyum-28 bakımından zengin kristal', ['Saf altın', 'Platin-iridyum alaşımından dökülmüş metal', 'Elmas kristali'], 'Avogadro projesinde silisyum-28 ile zenginleştirilmiş tek kristal küreler kullanılmış; kristal örgü aralığı ve kürenin hacmi ölçülerek içindeki atom sayısı hesaplanmıştır.'),
  ('1961\'de karbon-12 ölçeği benimsenmeden önce kimyacılar atom kütleleri için hangi elementi referans alıyordu?', 'Doğal oksijeni (16 kabul ederek)', ['Doğal hidrojeni (2 kabul ederek)', 'Doğal azotu (14,00 kabul ederek)', 'Doğal karbonu (12 kabul ederek)'], 'Kimyacılar doğal izotop karışımındaki oksijeni 16 kabul ediyordu; fizikçiler ise oksijen-16 izotopunu temel alıyordu. Bu ikilik 1961\'de karbon-12 ölçeğiyle giderildi.'),
  ('Karbon-12 ölçeğinin 1961\'de ortak atom kütlesi standardı olarak seçilmesinin başlıca nedeni neydi?', 'Fizikçilerle kimyacıların farklı oksijen ölçeklerini birleştirmek', ['Karbonun doğada tek izotoplu olması', 'Hidrojen ölçeğinin tam sayı sonuçlar vermesi', 'Karbon-12\'nin radyoaktif olduğu için kolayca ve hızla ölçülebilmesi'], 'İki farklı oksijen ölçeği arasındaki küçük farklar karışıklık yaratıyordu. Karbon-12 her iki toplulukça kabul edilen ortak bir referans oldu; karbonun kütle spektrometrisinde kullanımı da kolaydır.'),
  ('Bir elektronun kütlesi yaklaşık 9,1×10⁻²⁸ g\'dır. Bir mol elektronun kütlesi yaklaşık kaç gramdır? (NA = 6,0×10²³)', '5,5×10⁻⁴', ['1,0×10⁰', '9,1×10⁻⁵', '1,8×10⁻³'], '9,1×10⁻²⁸ g × 6,0×10²³ ≈ 5,5×10⁻⁴ g. Bir mol elektron, bir mol protonun (≈1 g) yaklaşık 1/1836\'sı kadardır.'),
  ('Doğal brom yaklaşık eşit oranda ⁷⁹Br ve ⁸¹Br izotoplarından oluşur. Br₂ moleküllerinin kütle spektrumunda molekül iyonu bölgesinde kaç tepe ve hangi yaklaşık şiddet oranı beklenir?', 'Üç tepe (158, 160, 162), oran 1:2:1', ['İki tepe (158 ve 162), şiddet oranı 1:1', 'Tek tepe', 'Dört tepe, eşit şiddette'], 'İki atom rastgele birleşir: ⁷⁹Br–⁷⁹Br, ⁷⁹Br–⁸¹Br (iki farklı yoldan) ve ⁸¹Br–⁸¹Br. Olasılıklar 1/4, 1/2, 1/4 olduğundan 1:2:1 oranı görülür.'),
  ('Neon-20 ve neon-22\'nin tek yüklü iyonları ile neon-20\'nin iki yüklü iyonu aynı hızla bir manyetik alana giriyor. Hangi iyonun yolu en çok sapar?', 'İki yüklü neon-20 iyonu', ['Tek yüklü neon-22 iyonu', 'Tek yüklü neon-20 iyonu', 'Üçünün sapması birbirine eşittir.'], 'Sapma kütle/yük oranı küçüldükçe artar. Oranlar ²⁰Ne⁺ için 20, ²²Ne⁺ için 22, ²⁰Ne²⁺ için 10\'dur; en küçük oran iki yüklü neon-20 iyonundadır.'),
  ('Bir atomun akb cinsinden kütlesinin kütle numarasından biraz farklı (örneğin ⁵⁶Fe için 55,935 akb) çıkmasının başlıca nedeni hangisidir?', 'Bağlanma enerjisine karşılık gelen kütle kaybı', ['Elektronların kütlesinin ihmal edilmesi', 'Ölçüm aletlerinin hassasiyetinin yetersiz olması', 'Avogadro sayısının yuvarlanması'], 'Nükleonlar çekirdekte birleşirken bağlanma enerjisi kadar kütle kaybı olur (E = mc²); ayrıca proton ve nötron kütleleri tam 1 akb değildir.'),
  ('İngiliz tuzu olarak bilinen MgSO₄·xH₂O\'nun 24,6 g\'ı ısıtılarak tüm suyu uzaklaştırıldığında 12,0 g susuz MgSO₄ kalıyor. x kaçtır? (MgSO₄ = 120, H₂O = 18 g/mol)', '7', ['5', '6', '10'], 'Susuz tuz 12,0/120 = 0,10 mol; su 12,6/18 = 0,70 mol\'dür. Oran 7 olduğundan formül MgSO₄·7H₂O\'dur.'),
  ('Bir öğrenci hidrat deneyinde ısıtmayı erken keserek suyun bir kısmını uzaklaştıramamıştır. Hesapladığı x (su sayısı) değeri gerçek değere göre nasıl çıkar?', 'Gerçek değerden küçük', ['Gerçek değerden büyük', 'Gerçek değere eşit', 'Kullanılan örnek kütlesine bağlı olarak negatif'], 'Uzaklaşmayan su, susuz tuzun kütlesine eklenmiş gibi görünür; ölçülen su kütlesi azalır, tuz mol sayısı artar. Bu yüzden su/tuz oranı olduğundan küçük bulunur.'),
  ('Sarı kan tuzu olarak bilinen potasyum hekzasiyanoferrat(II), K₄[Fe(CN)₆], bileşiğinin mol kütlesi kaç g/mol\'dür? (K = 39, Fe = 56, C = 12, N = 14)', '368', ['212', '329', '407,5'], '4×39 + 56 + 6×(12 + 14) = 156 + 56 + 156 = 368 g/mol.'),
  ('20 g ağır su (²H₂¹⁶O) örneğinde toplam kaç mol nötron bulunur? (²H: 1 nötron, ¹⁶O: 8 nötron, D₂O = 20 g/mol)', '10', ['8', '12', '20,0'], '20 g D₂O 1 mol\'dür. Her molekülde 2×1 + 8 = 10 nötron bulunduğundan toplam 10 mol nötron vardır.'),
  ('Toplam N tane atom içeren SO₂ örneği kaç gramdır? (S = 32, O = 16; N: Avogadro sayısı)', '64/3', ['64', '32', '64·3'], 'Her SO₂ molekülü 3 atomdur; N atom N/3 molekül, yani 1/3 mol eder. Kütle (1/3) × 64 = 64/3 g ≈ 21,3 g\'dır.'),
  ('Kaç gram metan (CH₄), 1 mol amonyak (NH₃) ile aynı sayıda atom içerir? (C = 12, H = 1)', '12,8', ['16', '20', '3,2'], '1 mol NH₃ 4 mol atom içerir. CH₄\'te molekül başına 5 atom olduğundan 4/5 = 0,8 mol CH₄ gerekir; 0,8 × 16 = 12,8 g.'),
  ('Wüstit gibi bazı katılar Fe₀,₉₅O biçiminde, bileşimi belirli sınırlar içinde değişebilen formüllere sahiptir. Bu tür katılar hangi yasanın kesin biçimine uymaz?', 'Sabit oranlar yasası', ['Kütlenin korunumu yasası', 'Birleşen hacimler yasası', 'Avogadro yasası'], 'Bileşimi değişebilen (stokiyometrik olmayan) katılarda elementlerin kütle oranı sabit değildir; bu nedenle sabit oranlar yasasının istisnası sayılırlar. Kütle yine de korunur.'),
  ('Proust ile bileşiklerin değişken bileşimli olabileceğini savunarak uzun bir tartışmaya giren Fransız kimyacı kimdir?', 'Claude Louis Berthollet', ['Antoine Laurent de Lavoisier', 'John Dalton', 'Jöns Jacob Berzelius'], 'Berthollet bileşimin oluşum koşullarına göre değişebileceğini savunmuş; tartışmayı saf bileşikler için Proust kazanmıştır. Değişken bileşimli katılara bugün onun adına "berthollid" de denir.'),
  ('CH₄ ve C₂H₆ bileşiklerinde eşit kütlede karbonla birleşen hidrojen kütleleri oranı (CH₄ / C₂H₆) kaçtır?', '4/3', ['2/3', '3/2', '1/2'], 'Karbon atomu başına CH₄\'te 4, C₂H₆\'da 3 hidrojen vardır. Eşit karbon kütlesi için hidrojen kütleleri oranı 4/3\'tür.'),
  ('X ve Y elementlerinden oluşan iki bileşikten I. bileşik kütlece %50 X, II. bileşik kütlece %40 X içeriyor. I. bileşiğin formülü XY ise II. bileşiğin formülü hangisidir?', 'X₂Y₃', ['XY₂', 'X₃Y₂', 'X₂Y'], 'I\'de 1 g X\'e 1 g Y, II\'de 1 g X\'e 60/40 = 1,5 g Y düşer. Y oranı 1 : 1,5 = 2 : 3 olduğundan XY\'ye karşılık II. bileşik X₂Y₃\'tür.'),
  ('XY₂ bileşiğinde X\'in Y\'ye kütle oranı 3/8\'dir. X ve Y\'nin atom kütleleri oranı (X/Y) kaçtır?', '3/4', ['3/8', '3/16', '8/3'], 'Bir molekülde 1 X ve 2 Y vardır: X / (2Y) = 3/8, buradan X/Y = 6/8 = 3/4. (CO₂ buna örnektir: 12/16 = 3/4.)'),
  ('Gaz hâlindeki bir hidrokarbonun 10 mL\'si aynı koşullarda 30 mL O₂ ile tamamen yanarak 20 mL CO₂ ve sıvı su oluşturuyor. Hidrokarbonun formülü hangisidir?', 'C₂H₄', ['C₂H₆', 'C₃H₆', 'CH₄'], 'CₓHᵧ için 10 mL\'den 20 mL CO₂ çıktığından x = 2\'dir. Harcanan O₂ oranı x + y/4 = 3 olduğundan y = 4; formül C₂H₄\'tür.'),
  ('Aynı koşullarda ölçülen ve CH₄ ile C₂H₆\'dan oluşan 10 L\'lik bir gaz karışımı tamamen yakıldığında 14 L CO₂ oluşuyor. Karışımda kaç litre CH₄ vardır?', '6', ['4', '7', '8,5'], 'CH₄ x L, C₂H₆ y L ise x + y = 10 ve x + 2y = 14\'tür. Buradan y = 4, x = 6 L bulunur.'),
  ('3O₂(g) → 2O₃(g) tepkimesine göre 30 mL oksijenin 9 mL\'si aynı koşullarda ozona dönüşüyor. Son durumda toplam gaz hacmi kaç mL\'dir?', '27', ['21', '24', '30'], '9 mL O₂\'den 9 × 2/3 = 6 mL O₃ oluşur; 21 mL O₂ dönüşmeden kalır. Toplam 21 + 6 = 27 mL.'),
  ('Bir demir oksit kütlece %72,4 demir ve %27,6 oksijen içermektedir. Bu oksidin basit formülü hangisidir? (Fe = 56, O = 16)', 'Fe₃O₄', ['Fe₂O₃', 'FeO', 'Fe₄O₃'], 'Fe: 72,4/56 ≈ 1,29; O: 27,6/16 ≈ 1,73. O/Fe ≈ 1,33 = 4/3 olduğundan tam sayıya çevirmek için 3 ile çarpılır: Fe₃O₄ (manyetit).'),
  ('Klasik yakma analizi düzeneğinde suyu tutan tüpün, CO₂\'yi tutan bazik tüpten önce yerleştirilmesinin nedeni nedir?', 'Bazik tutucu nemi de çeker; su önce alınmazsa CO₂ fazla ölçülür.', ['Su, CO₂\'yi tutan tüpteki bazla patlayıcı bir tepkime verdiğinden', 'CO₂ önce tutulursa su buharı yoğuşamadığından', 'Tüplerin sırası sonucu etkilemez; bu sıra yalnızca bir gelenektir.'], 'CO₂ tutucu bazik maddeler (örneğin NaOH) suyu da tutar. Su önce ayrı bir kurutucuyla alınmazsa CO₂ tüpündeki kütle artışı gerçeğinden büyük çıkar.'),
  ('C, H ve O içeren 3,0 g bileşik yakıldığında 4,4 g CO₂ ve 1,8 g H₂O oluşuyor. Bileşiğin mol kütlesi 60 g/mol ise molekül formülü hangisidir? (C = 12, H = 1, O = 16)', 'C₂H₄O₂', ['CH₂O', 'C₃H₈O', 'C₂H₆O₂·H₂O'], 'C: 4,4/44 = 0,1 mol (1,2 g); H: 2 × 1,8/18 = 0,2 mol (0,2 g); O: 3,0 − 1,4 = 1,6 g = 0,1 mol. Basit formül CH₂O (30); 60/30 = 2 olduğundan C₂H₄O₂.'),
  ('Yalnız C ve H içerdiği düşünülen 2,9 g\'lık bir bileşik yakıldığında 8,8 g CO₂ ve 4,5 g H₂O oluşuyor. Bu verilerden hangi sonuca ulaşılır? (C = 12, H = 1, O = 16)', 'Oksijen içermez; basit formülü C₂H₅\'tir.', ['Oksijen içerir; basit formülü C₂H₅O\'dur.', 'Oksijen içermez; basit formülü CH₃\'tür.', 'Oksijen içerir; basit formülü CH₂O\'dur ve molekülü polardır.'], 'C: 0,2 mol = 2,4 g; H: 0,5 mol = 0,5 g. Toplam 2,9 g, örnek kütlesine eşit olduğundan oksijen yoktur. C : H = 0,2 : 0,5 = 2 : 5.'),
  ('Bir protein örneği kütlece %0,34 demir içermektedir. Her molekülde en az bir demir atomu bulunduğuna göre proteinin en küçük mol kütlesi yaklaşık kaç g/mol\'dür? (Fe = 56)', '16 500', ['1 650', '165 000', '5 600'], 'Bir molekülde en az 56 g/mol demir vardır: M_min = 56 / 0,0034 ≈ 16 500 g/mol. (Hemoglobinde 4 Fe bulunduğundan gerçek değer yaklaşık dört katıdır.)'),
  ('Manyetitle yapılan termit tepkimesi Fe₃O₄ + Al → Al₂O₃ + Fe en küçük tam sayılarla denkleştirildiğinde alüminyumun katsayısı kaç olur?', '8', ['2', '12', '9'], 'Oksijenler için 3Fe₃O₄ (12 O) ve 4Al₂O₃ (12 O) gerekir; buradan 8Al ve 9Fe gelir: 3Fe₃O₄ + 8Al → 4Al₂O₃ + 9Fe.'),
  ('Bakırın seyreltik nitrik asitle tepkimesi Cu + HNO₃ → Cu(NO₃)₂ + NO + H₂O denklemiyle gösterilir. En küçük tam sayılarla denkleştirildiğinde HNO₃\'ün katsayısı kaçtır?', '8', ['4', '6', '10'], 'Cu 2 elektron verir, N (+5\'ten +2\'ye) 3 elektron alır; 3Cu ve 2NO gerekir. Nitratlar ve oksijenler dengelenince 3Cu + 8HNO₃ → 3Cu(NO₃)₂ + 2NO + 4H₂O olur.'),
  ('KMnO₄ + HCl → KCl + MnCl₂ + Cl₂ + H₂O denklemi en küçük tam sayılarla denkleştirildiğinde HCl\'nin katsayısı kaç olur?', '16', ['8', '10', '14'], 'Mn 5 elektron alır, her Cl⁻ 1 elektron verir: 2KMnO₄ ile 5Cl₂ eşleşir. Tamamı: 2KMnO₄ + 16HCl → 2KCl + 2MnCl₂ + 5Cl₂ + 8H₂O.'),
  ('4Al + 3O₂ → 2Al₂O₃ tepkimesi için eşit mol sayılarında Al ve O₂ alınıp tam verimle tepkime gerçekleştiriliyor. Tepkime sonunda hangisi doğrudur?', 'Başlangıçtaki O₂\'nin %25\'i artar.', ['Başlangıçtaki Al\'nin %25\'i artar.', 'Her iki madde de artansız olarak tamamen tükenir.', 'Başlangıçtaki O₂\'nin %75\'i artar.'], 'Her birinden n mol varsa, n mol Al ancak 3n/4 mol O₂ harcar. Geriye n/4 mol, yani O₂\'nin %25\'i kalır; Al sınırlayıcıdır.'),
  ('Kapalı bir kapta 0,1 mol propan ile 0,4 mol O₂ bulunuyor. Tam yanma tepkimesi C₃H₈ + 5O₂ → 3CO₂ + 4H₂O\'ya göre gerçekleşirse en çok kaç mol CO₂ oluşur?', '0,24', ['0,32', '0,40', '0,08'], '0,1 mol propan için 0,5 mol O₂ gerekir; O₂ sınırlayıcıdır. 0,4 / 5 = 0,08 mol propan yanar ve 0,08 × 3 = 0,24 mol CO₂ oluşur.'),
  ('Her basamağı %90 verimle gerçekleşen 10 basamaklı bir ilaç sentezinin toplam verimi yaklaşık yüzde kaçtır?', '35', ['90', '10', '81'], 'Toplam verim 0,90¹⁰ ≈ 0,35\'tir. Basamak sayısı arttıkça yüksek verimli basamaklar bile toplam verimi hızla düşürür.'),
  ('Kütlece %80 Fe₂O₃ içeren 1 ton demir cevheri işleniyor ve demir %90 verimle elde ediliyor. Kaç ton demir üretilir? (Fe = 56, O = 16)', '0,504', ['0,560', '0,720', '0,448'], 'Cevherde 0,8 ton Fe₂O₃ vardır; bunun 112/160\'ı demirdir: 0,56 ton. %90 verimle 0,56 × 0,9 = 0,504 ton.'),
  ('Nitrik asit üretiminde 4NH₃ + 5O₂ → 4NO + 6H₂O, 2NO + O₂ → 2NO₂ ve 3NO₂ + H₂O → 2HNO₃ + NO tepkimeleri gerçekleşir. Son basamakta oluşan NO geri döndürülmezse 1 mol NH₃\'ten en çok kaç mol HNO₃ elde edilir?', '2/3', ['1', '1/3', '3/2'], '1 mol NH₃ → 1 mol NO → 1 mol NO₂ verir. 3 mol NO₂\'den 2 mol HNO₃ oluştuğundan 1 mol NO₂\'den 2/3 mol HNO₃ elde edilir.'),
  ('0,2 mol KClO₃\'ün 2KClO₃ → 2KCl + 3O₂ tepkimesiyle tamamen ayrışmasından elde edilen oksijenle 2Mg + O₂ → 2MgO tepkimesine göre en çok kaç gram magnezyum yakılabilir? (Mg = 24)', '14,4', ['7,2', '9,6', '4,8'], '0,2 mol KClO₃\'ten 0,3 mol O₂ oluşur. Her O₂ iki Mg yaktığından 0,6 mol Mg = 0,6 × 24 = 14,4 g yakılabilir.'),
  ('NaCl ve KCl\'den oluşan 13,3 g\'lık bir karışım suda çözülüp yeterli AgNO₃ eklendiğinde toplam 0,2 mol AgCl çöküyor. Karışımda kaç gram NaCl vardır? (NaCl = 58,5, KCl = 74,5 g/mol)', '5,85', ['7,45', '11,7', '6,65'], 'NaCl a mol, KCl b mol ise a + b = 0,2 ve 58,5a + 74,5b = 13,3\'tür. Çözüm a = b = 0,1; NaCl kütlesi 0,1 × 58,5 = 5,85 g.'),
  ('NaHCO₃ ve Na₂CO₃\'ten oluşan 27,4 g\'lık bir karışım ısıtıldığında 2NaHCO₃ → Na₂CO₃ + H₂O(g) + CO₂(g) tepkimesi sonucu kütle 3,1 g azalıyor. Karışımda kaç gram NaHCO₃ vardır? (NaHCO₃ = 84, H₂O = 18, CO₂ = 44 g/mol)', '8,4', ['4,2', '16,8', '19,0'], 'Her 2 mol NaHCO₃ ayrışınca 18 + 44 = 62 g gaz çıkar. 3,1 g kayıp 0,05 × 2 = 0,1 mol NaHCO₃\'e karşılık gelir: 0,1 × 84 = 8,4 g.'),
  ('Bir gübre örneğinin 1,00 g\'ındaki fosforun tamamı Mg₂P₂O₇ olarak çöktürülüp 0,222 g tartılıyor. Örnek kütlece yüzde kaç fosfor içerir? (Mg₂P₂O₇ = 222 g/mol, P = 31)', '6,2', ['3,1', '12,4', '22,2'], '0,222 / 222 = 0,001 mol Mg₂P₂O₇ vardır; içinde 0,002 mol P = 0,062 g bulunur. 0,062 / 1,00 × 100 = %6,2.'),
  ('Bir öğrenci sınırlayıcı bileşeni her zaman "kütlesi en az olan madde" diye seçiyor. 2H₂ + O₂ → 2H₂O tepkimesi için aşağıdaki karışımlardan hangisi bu yöntemin yanlış olduğunu gösterir? (H = 1, O = 16)', '4 g H₂ ve 16 g O₂', ['4 g H₂ ve 64 g O₂', '1 g H₂ ve 32 g O₂', '2 g H₂ ve 16 g O₂'], '4 g H₂ (2 mol) 1 mol (32 g) O₂ ister; 16 g O₂ yetmez. Kütlesi az olan H₂ değil O₂ sınırlayıcıdır. 2 g H₂ ile 16 g O₂ ise tam oranlıdır.'),
  ('Eşit kütlelerde alınan magnezyum ve alüminyum yeterli HCl ile ayrı ayrı tepkimeye giriyor. Açığa çıkan hidrojen için hangisi doğrudur? (Mg = 24, Al = 27)', 'Alüminyumdan daha fazla H₂ çıkar.', ['Magnezyumdan daha fazla H₂ çıkar.', 'İkisinden de eşit miktarda H₂ çıkar.', 'Atom kütlesi küçük olduğu için yalnız magnezyum H₂ çıkarır.'], 'm gram Mg, m/24 mol H₂; m gram Al ise 1,5 × m/27 = m/18 mol H₂ verir. m/18 > m/24 olduğundan alüminyum daha çok H₂ açığa çıkarır.'),
  ('Atom kütlelerini olağanüstü bir doğrulukla belirleyen çalışmaları nedeniyle 1914 Nobel Kimya Ödülü\'nü alan Amerikalı kimyacı kimdir?', 'Theodore W. Richards', ['Irving Langmuir', 'Gilbert Newton Lewis', 'Linus Carl Pauling'], 'Theodore W. Richards, pek çok elementin atom kütlesini gravimetrik yöntemlerle çok hassas ölçmüş ve 1914\'te Nobel Kimya Ödülü\'nü alan ilk Amerikalı olmuştur.'),
  ('Dulong-Petit kuralına göre katı elementlerin molar ısı kapasitesi yaklaşık 25 J/(mol·K)\'dir. Özgül ısısı 0,13 J/(g·K) ölçülen katı bir metalin atom kütlesi yaklaşık kaçtır?', '190', ['25', '3,3', '3250'], 'Molar ısı kapasitesi = özgül ısı × atom kütlesi olduğundan atom kütlesi ≈ 25 / 0,13 ≈ 190 bulunur (altın, 197\'ye yakın). 19. yüzyılda atom kütlelerini kestirmede bu yol kullanılmıştır.'),
  ('Cannizzaro\'nun yöntemine göre bir elementin atom kütlesi, o elementi içeren pek çok bileşiğin 1 molündeki element kütlelerinin en büyük ortak böleni olarak alınır. X içeren bileşiklerin 1\'er molünde 14 g, 28 g ve 42 g X bulunuyorsa X\'in atom kütlesi büyük olasılıkla kaçtır?', '14', ['7', '28', '42'], 'Bir bileşiğin molünde en az bir X atomu bulunur; bütün değerlerin en büyük ortak böleni 14 olduğundan X\'in atom kütlesi büyük olasılıkla 14\'tür (azot).'),
  ('IUPAC\'ın 2009\'dan bu yana hidrojen, karbon, azot ve oksijen gibi bazı elementlerin standart atom kütlesini tek bir sayı yerine bir aralık olarak vermesinin nedeni nedir?', 'Doğal izotop bileşiminin kaynağa göre değişmesi', ['Bu elementlerin atom kütlelerinin hiç ölçülememiş olması', 'Elementlerin radyoaktif bozunarak kütle kaybetmesi', 'Karbon-12 ölçeğinin bu elementler için geçersiz olması'], 'Örneğin farklı kaynaklardaki karbonun ¹³C oranı biraz farklıdır; bu nedenle tek bir değer bütün doğal örnekleri temsil edemez ve aralık verilir.'),
  ('Elementlerin atom kütlelerini 1818 ve 1828\'de yayımladığı tablolarla dönemin en doğru biçimde belirleyen ve oksijeni 100 kabul eden bir ölçek kullanan İsveçli kimyacı kimdir?', 'Jöns J. Berzelius', ['Carl Wilhelm Scheele', 'Anders Celsius', 'Svante Arrhenius'], 'Berzelius çok sayıda bileşiği analiz ederek atom kütlesi tabloları hazırlamış, oksijeni 100 alan bir ölçek kullanmıştır; bugünkü harf simgeleri sistemi de ona dayanır.'),
  ('Belçikalı kimyacı Jean Servais Stas\'ın 19. yüzyılın ortalarında yaptığı son derece hassas atom kütlesi ölçümleri hangi sonucu doğurmuştur?', 'Prout hipotezine ciddi biçimde itiraz edilmesine yol açmıştır.', ['Avogadro sayısının ilk kez ölçülmesini sağlamıştır.', 'Elektronun kütlesinin belirlenmesine yol açmıştır.', 'Karbon-12 ölçeğinin uluslararası olarak kabul edilmesini sağlamıştır.'], 'Stas, gümüş ve klor gibi elementlerin atom kütlelerini çok duyarlı ölçmüş ve bunların hidrojenin tam katları olmadığını göstererek Prout hipotezini güçlü biçimde zayıflatmıştır.'),
  ('Süperfosfat gübresi Ca₃(PO₄)₂ + 2H₂SO₄ → Ca(H₂PO₄)₂ + 2CaSO₄ tepkimesiyle üretilir. 310 kg fosfat kayası için en az kaç kg H₂SO₄ gerekir? (Ca₃(PO₄)₂ = 310, H₂SO₄ = 98 g/mol)', '196', ['98', '310', '392'], '310 kg Ca₃(PO₄)₂ = 1 kmol\'dür ve 2 kmol H₂SO₄ ister: 2 × 98 = 196 kg.'),
  ('Kemik ve diş mineinin ana bileşeni hidroksiapatitin formülü Ca₁₀(PO₄)₆(OH)₂\'dir (yaklaşık 1004 g/mol). Bu mineralde kalsiyumun kütlece yüzdesi yaklaşık kaçtır? (Ca = 40)', '%40', ['%10', '%25', '%30'], 'Bir formül biriminde 10 × 40 = 400 g kalsiyum vardır. 400 / 1004 × 100 ≈ %40.'),
  ('İki atomlu X₂ gazının a gramında N tane X atomu bulunmaktadır. X\'in atom kütlesi hangisidir? (NA: Avogadro sayısı)', 'a·NA/N', ['2a·NA/N', 'a·N/NA', 'a·NA/(2N)'], 'N atom N/NA mol atomdur. Bu atomların kütlesi a gram olduğundan atom kütlesi a ÷ (N/NA) = a·NA/N olur; X₂ olması atom sayısını zaten içerir.'),
  ('1\'er gram H₂, He ve CH₄ örneklerindeki toplam atom sayılarının doğru sıralaması hangisidir? (H = 1, He = 4, C = 12)', 'H₂ > CH₄ > He', ['CH₄ > H₂ > He', 'He > H₂ > CH₄', 'H₂ > He > CH₄'], 'Atom molleri: H₂ için (1/2) × 2 = 1; CH₄ için (1/16) × 5 ≈ 0,31; He için 1/4 = 0,25. Sıralama H₂ > CH₄ > He olur.'),
  ('Eşit sayıda oksijen atomu içeren SO₂ ve SO₃ örneklerinin kütleleri oranı (SO₂ / SO₃) kaçtır? (S = 32, O = 16)', '6/5', ['4/5', '2/3', '1'], '6 mol O için 3 mol SO₂ (192 g) ya da 2 mol SO₃ (160 g) gerekir. Oran 192/160 = 6/5\'tir.'),
  ('Kapalı bir kapta 1,2 mol karbon ile 1,0 mol O₂ ısıtılıyor; oksijenin tamamı ve karbonun tamamı tükenerek CO ile CO₂ karışımı oluşuyor. Karışımda kaç mol CO vardır?', '0,4', ['0,8', '0,2', '1,2'], 'CO₂ a mol, CO b mol olsun. Karbon: a + b = 1,2; oksijen molekülü: a + b/2 = 1,0. Çıkarma ile b/2 = 0,2, b = 0,4 mol CO (a = 0,8 mol CO₂).'),
  ('1 mol sıvı su donduğunda hacmi yaklaşık kaç cm³ artar? (H₂O = 18 g/mol; sıvı suyun yoğunluğu 1,00 g/cm³, buzun yoğunluğu 0,92 g/cm³)', '1,6', ['0,92', '18', '19,6'], '18 g su sıvıyken 18 cm³, buzken 18 / 0,92 ≈ 19,6 cm³ yer kaplar. Artış yaklaşık 1,6 cm³\'tür.'),
  ('Bakırın yoğunluğu 8,96 g/cm³, atom kütlesi 63,5\'tir. Katı bakırda bir atoma düşen ortalama hacim yaklaşık kaç cm³\'tür? (NA = 6,02×10²³)', '1,2×10⁻²³', ['7,1×10⁰', '8,5×10⁻²⁴', '1,2×10⁻²⁰'], '1 mol bakırın hacmi 63,5 / 8,96 ≈ 7,09 cm³\'tür. Bu hacim NA atoma bölünür: 7,09 / 6,02×10²³ ≈ 1,2×10⁻²³ cm³.'),
  ('Eşit hacimlerde alınan su (yoğunluk 1,00 g/mL, 18 g/mol) ve etil alkol (yoğunluk 0,79 g/mL, 46 g/mol) örneklerinde su moleküllerinin sayısı alkol moleküllerinin yaklaşık kaç katıdır?', '3,2', ['1,3', '2,6', '0,31'], '1 mL için su 1/18 ≈ 0,0556 mol, alkol 0,79/46 ≈ 0,0172 mol\'dür. Oran 0,0556 / 0,0172 ≈ 3,2.'),
  ('Bir öğrenci CuSO₄ çözeltisini elektroliz ederek katotta 0,01 mol bakır (Cu²⁺ + 2e⁻ → Cu) biriktiriyor ve devreden 1930 C yük geçtiğini ölçüyor. Elektronun yükü 1,6×10⁻¹⁹ C alınırsa Avogadro sayısı yaklaşık kaç bulunur?', '6,0×10²³', ['3,0×10²³', '1,2×10²⁴', '1,2×10²²'], 'Geçen elektron sayısı 1930 / 1,6×10⁻¹⁹ ≈ 1,2×10²² tanedir. Bu, 0,02 mol elektrona karşılık gelir; NA ≈ 1,2×10²² / 0,02 ≈ 6,0×10²³.'),
  ('X-ışını kırınımıyla Avogadro sayısının belirlenmesinde saf bir kristal için hangi nicelikler birlikte kullanılır?', 'Hücre boyutu, yoğunluk, mol kütlesi', ['Erime noktası, rengi ve sertliği', 'Kaynama noktası, buhar basıncı ve yoğunluk', 'Elektrik iletkenliği ve ısı kapasitesi'], 'Birim hücrenin hacmi ve içindeki atom sayısı X-ışınlarıyla bulunur; yoğunluk ve mol kütlesiyle birleştirilerek bir moldeki atom sayısı hesaplanır.'),
  ('Rutherford ve Boltwood, radyumdan yayılan alfa parçacıklarını sayıp bunların oluşturduğu helyum gazının miktarını ölçerek hangi niceliği hesaplayabilmiştir?', 'Avogadro sayısını', ['Elektronun kütlesini', 'Işık hızını', 'Planck sabitini'], 'Sayılan alfa parçacıkları helyum atomlarına dönüşür; atom sayısı ile helyumun mol miktarı karşılaştırılarak bir moldeki tanecik sayısı bulunmuştur.'),
  ('MO formülündeki bir metal oksidin 8,0 g\'ı hidrojenle tamamen indirgendiğinde (MO + H₂ → M + H₂O) 1,8 g su oluşuyor. M\'nin atom kütlesi kaçtır? (H = 1, O = 16)', '64', ['56', '40', '72,5'], '1,8 g su 0,1 mol\'dür; oksitteki oksijen de 0,1 mol (1,6 g) olur. Metal 8,0 − 1,6 = 6,4 g = 0,1 mol, atom kütlesi 64\'tür (bakır).'),
  ('MCl₂ formülündeki bir klorürün 2,22 g\'ı suda çözülüp yeterli AgNO₃ eklendiğinde 5,74 g AgCl çöküyor. M hangi elementtir? (AgCl = 143,5 g/mol; Cl = 35,5; Mg = 24, Ca = 40, Sr = 88, Ba = 137)', 'Kalsiyum', ['Magnezyum', 'Stronsiyum', 'Baryum'], '5,74 / 143,5 = 0,04 mol Cl⁻ → 0,02 mol MCl₂. Mol kütlesi 2,22 / 0,02 = 111; M = 111 − 71 = 40, yani kalsiyum.'),
  ('Kuru havada oksijenin mol (hacim) yüzdesi yaklaşık %21\'dir ve geri kalanın azot olduğu varsayılıyor. Havada oksijenin kütlece yüzdesi yaklaşık kaçtır? (N₂ = 28, O₂ = 32 g/mol)', '%23', ['%21', '%32', '%19'], '100 mol havada 21 × 32 = 672 g O₂ ve 79 × 28 = 2212 g N₂ vardır. 672 / 2884 ≈ %23. Oksijen azottan ağır olduğu için kütlece payı biraz daha büyüktür.'),
  ('Bir öğrenci yüzde verimi hesaplarken kuramsal verimi yanlışlıkla sınırlayıcı bileşen yerine artan bileşene göre buluyor. Hesapladığı yüzde verim gerçek değere göre nasıl çıkar?', 'Olduğundan küçük', ['Olduğundan büyük', 'Değişmez', 'Her durumda tam olarak %100'], 'Artan bileşene göre hesaplanan kuramsal verim gerçekte oluşabilecek en yüksek miktardan büyüktür. Payda büyüyünce yüzde verim olduğundan küçük çıkar.'),
  ('1\'er gram H₂O ve D₂O (ağır su) örnekleri karşılaştırıldığında toplam proton sayısı için hangisi doğrudur? (H₂O = 18, D₂O = 20 g/mol)', 'H₂O örneğinde daha çoktur.', ['D₂O örneğinde daha fazladır.', 'İki örnekte eşittir.', 'Karşılaştırma yapılamaz.'], 'Her iki molekülde de 10 proton vardır. Aynı kütlede H₂O daha çok molekül (1/18 > 1/20 mol) içerdiğinden toplam proton sayısı H₂O\'da fazladır.'),
  ('Nitrogliserinin patlaması 4C₃H₅N₃O₉ → 12CO₂ + 10H₂O + 6N₂ + O₂ denklemiyle gösterilir. 4 mol nitrogliserin patladığında toplam kaç mol gaz oluşur (su buhar hâlindedir)?', '29', ['12', '19', '23'], '12 + 10 + 6 + 1 = 29 mol gaz oluşur. Sıvı bir maddeden bu kadar çok gaz çıkması patlamanın şiddetini açıklar.'),
  ('2Al + 3S → Al₂S₃ tepkimesinde 5,4 g Al ile 8,0 g S karıştırılıp tepkime %80 verimle gerçekleştiriliyor. Kaç gram Al₂S₃ elde edilir? (Al = 27, S = 32; Al₂S₃ = 150 g/mol)', '10', ['12,5', '16', '8,0'], 'Al 0,2 mol, S 0,25 mol\'dür. 0,2 mol Al için 0,3 mol S gerekir; S sınırlayıcıdır. Kuramsal ürün 0,25/3 mol × 150 = 12,5 g; %80\'i 10 g\'dır.'),
  ('Turuncu renkli bir tuz kütlece %26,6 K, %35,4 Cr ve %38,1 O içermektedir. Tuzun basit formülü hangisidir? (K = 39, Cr = 52, O = 16)', 'K₂Cr₂O₇', ['K₂CrO₄', 'KCrO₂', 'K₃CrO₈'], 'K: 26,6/39 ≈ 0,68; Cr: 35,4/52 ≈ 0,68; O: 38,1/16 ≈ 2,38. Oran 1 : 1 : 3,5, yani 2 : 2 : 7\'dir; formül K₂Cr₂O₇ (potasyum dikromat).'),
  ('C vitamini (askorbik asit) kütlece %40,9 C, %4,6 H ve %54,5 O içerir ve mol kütlesi 176 g/mol\'dür. Molekül formülü hangisidir? (C = 12, H = 1, O = 16)', 'C₆H₈O₆', ['C₃H₄O₃', 'C₆H₁₂O₆', 'C₅H₈O₇'], 'Mol oranları 3,41 : 4,6 : 3,41 ≈ 3 : 4 : 3; basit formül C₃H₄O₃ (88 g/mol). 176/88 = 2 olduğundan molekül formülü C₆H₈O₆\'dır.'),
  ('3,25 g çinko asitle tepkimeye girerek normal koşullarda 1,12 L hidrojen gazı açığa çıkarıyor. Bu verilere göre çinkonun eşdeğer kütlesi kaç g/eş\'tir?', '32,5', ['65', '16,25', '13'], '1,12 L H₂ = 0,05 mol = 0,1 mol hidrojen eşdeğeri (0,1 mol elektron). Eşdeğer kütle = 3,25 / 0,1 = 32,5 g/eş.'),
  ('Metanın klorlanmasında CH₄ + Cl₂ → CH₃Cl + HCl tepkimesi gerçekleşiyor. İstenen ürün CH₃Cl ise bu tepkimenin atom ekonomisi yaklaşık yüzde kaçtır? (C = 12, H = 1, Cl = 35,5)', '58', ['100', '42', '50'], 'Girenlerin toplam kütlesi 16 + 71 = 87; CH₃Cl 50,5 g/mol. Atom ekonomisi = 50,5 / 87 × 100 ≈ %58\'dir.'),
  ('NO₂ ve N₂O₄ bileşikleri için katlı oranlar yasasının uygulanabileceği söylenebilir mi?', 'Hayır; iki formülün kütlece bileşimi aynıdır, aynı basit formüle sahiptirler.', ['Evet; 1 g azotla birleşen oksijen kütleleri 1 : 2 oranındadır.', 'Evet; çünkü ikisi de azot ve oksijenden oluşmuştur.', 'Hayır; çünkü yasa yalnız iyonik bileşikler için geçerlidir.'], 'NO₂ ve N₂O₄\'te N : O kütle oranı aynıdır (14 : 32). Katlı oranlar yasası, aynı elementlerin kütle bileşimi farklı bileşiklerini karşılaştırır.'),
  ('İzopropil alkolün yanma tepkimesi C₃H₈O + O₂ → CO₂ + H₂O en küçük tam sayılarla denkleştirilirse katsayıların toplamı kaç olur?', '25', ['22', '18', '24'], '2C₃H₈O + 9O₂ → 6CO₂ + 8H₂O biçiminde denkleşir. Katsayılar toplamı 2 + 9 + 6 + 8 = 25\'tir.'),
  ('Safsızlık içeren bir sofra tuzu örneğinin 10 g\'ı suda çözülüp fazla AgNO₃ eklenince 14,35 g AgCl çöküyor. Örneğin kütlece yüzde kaçı NaCl\'dir? (Na = 23, Cl = 35,5, Ag = 108)', '58,5', ['29,3', '71,8', '85,0'], '14,35 / 143,5 = 0,1 mol AgCl; Cl⁻ kaynağı NaCl olduğundan 0,1 mol NaCl vardır. 5,85 g / 10 g × 100 = %58,5.'),
  ('2H₂O₂ → 2H₂O + O₂ tepkimesinde istenen ürün oksijen gazıdır. Bu işlemin atom ekonomisi yaklaşık yüzde kaçtır? (H = 1, O = 16)', '47', ['53', '100', '32'], 'Girenlerin kütlesi 2 × 34 = 68; istenen ürün O₂ 32\'dir. 32 / 68 × 100 ≈ %47\'dir.'),
  ('M₂O₃ formülündeki bir oksitte M kütlece %52,9 oranındadır. M hangi elementtir? (O = 16; atom kütleleri: B = 11, Al = 27, Cr = 52, Fe = 56)', 'Al', ['B', 'Cr', 'Fe'], 'M₂O₃\'te oksijen 48 g\'dır. 2M / (2M + 48) = 0,529 denkleminden M ≈ 27 bulunur ve element alüminyumdur.'),
  ('Mol kütlesi 58 g/mol olan bir hidrokarbonun 2,9 g\'ı yakıldığında 8,8 g CO₂ ve 4,5 g H₂O oluşuyor. Molekül formülü nedir? (C = 12, H = 1, O = 16)', 'C₄H₁₀', ['C₂H₅', 'C₄H₈', 'C₃H₈'], '0,2 mol CO₂ ve 0,25 mol H₂O; C : H = 0,2 : 0,5 = 2 : 5. Basit formül C₂H₅ (29 g/mol), 58 / 29 = 2 olduğundan C₄H₁₀\'dur.'),
  ('Saf bakır çubuk AgNO₃ çözeltisine batırılıp Cu + 2Ag⁺ → Cu²⁺ + 2Ag tepkimesi yürütülüyor. Çubuğun kütlesi 7,6 g arttığına göre çubuk üzerinde kaç gram gümüş birikmiştir? (Cu = 64, Ag = 108)', '10,8', ['7,6', '21,6', '0,108'], '1 mol Cu çözününce 2 mol Ag (216 g) birikir; kütle artışı 216 − 64 = 152 g\'dır. 7,6 / 152 = 0,05 mol Cu, yani 0,1 mol Ag = 10,8 g.'),
  ('Demir çubuk CuSO₄ çözeltisine batırılıyor ve Fe + Cu²⁺ → Fe²⁺ + Cu tepkimesi gerçekleşiyor. Çubuğun kütlesi 1,6 g arttıysa çubukta kaç gram bakır birikmiştir? (Fe = 56, Cu = 64)', '12,8', ['0,128', '6,4', '11,2'], '1 mol Fe çözünüp 1 mol Cu biriktiğinde kütle 64 − 56 = 8 g artar. 1,6 / 8 = 0,2 mol Cu, yani 12,8 g bakır birikmiştir.'),
  ('Mg ve Al\'den oluşan 5,1 g karışım fazla HCl ile tepkimeye girdiğinde toplam 0,25 mol H₂ açığa çıkıyor. Karışımdaki magnezyum kaç gramdır? (Mg = 24, Al = 27)', '2,4', ['1,2', '2,7', '0,24'], 'Mg x mol, Al y mol olsun: 24x + 27y = 5,1 ve x + 1,5y = 0,25. Çözümle x = y = 0,1 mol bulunur; Mg kütlesi 2,4 g\'dır.'),
  ('CaCO₃ ve MgCO₃ içeren 1,84 g karışım fazla asitle tepkimeye girdiğinde 0,02 mol CO₂ açığa çıkıyor. Karışımda kaç gram CaCO₃ vardır? (CaCO₃ = 100, MgCO₃ = 84 g/mol)', '1,00', ['0,84', '0,100', '1,68'], 'x + y = 0,02 ve 100x + 84y = 1,84 denklemlerinden x = 0,01 mol CaCO₃ bulunur. Kütle 1,00 g\'dır.'),
  ('Laboratuvarda oksijen elde etmek için 2KClO₃ → 2KCl + 3O₂ tepkimesi kullanılıyor. Yalnız O₂ istenen ürünse bu işlemin atom ekonomisi yaklaşık yüzde kaçtır? (K = 39, Cl = 35,5, O = 16)', '39', ['61', '78', '100'], 'Girenlerin kütlesi 2 × 122,5 = 245; O₂ kütlesi 3 × 32 = 96\'dır. 96 / 245 × 100 ≈ %39.'),
  ('Eşit kütlelerde Mg, Al ve Zn örnekleri fazla seyreltik asitle tamamen tepkimeye giriyor. Açığa çıkan H₂ miktarı için hangi sıralama doğrudur? (Mg = 24, Al = 27, Zn = 65; Mg ve Zn +2, Al +3 verir)', 'Al > Mg > Zn', ['Zn > Mg > Al', 'Mg > Al > Zn', 'Al > Mg = Zn'], '1 g metal için H₂ mol sayıları: Al 1,5/27 ≈ 0,056; Mg 1/24 ≈ 0,042; Zn 1/65 ≈ 0,015. Sıra Al > Mg > Zn\'dir.'),
  ('1\'er gram CH₄, C₂H₆, C₃H₈ ve C₄H₁₀ tamamen yakıldığında en çok CO₂ hangi hidrokarbondan oluşur? (C = 12, H = 1)', 'C₄H₁₀', ['CH₄', 'C₂H₆', 'C₃H₈'], '1 g örnekten oluşan CO₂ mol sayıları: 1/16, 2/30, 3/44, 4/58 → 0,0625; 0,0667; 0,0682; 0,0690. En büyüğü C₄H₁₀\'dur.'),
  ('Bir hidrokarbonun kütle spektrumunda molekül iyonu tepesinin (M) bir birim ağırlığındaki tepenin (M+1) şiddeti M\'nin %5,5\'i kadardır. Bu fark yalnız ¹³C izotopundan (bolluk %1,1) kaynaklanıyorsa molekülde kaç karbon atomu vardır?', '5', ['4', '6', '11'], 'Her karbon atomu M+1 tepesine yaklaşık %1,1 katkı yapar. 5,5 / 1,1 = 5 karbon atomu bulunur.'),
  ('Normal koşullarda 1 cm³ ideal gazda yaklaşık kaç molekül bulunur? (Bu değer Loschmidt sayısıdır; NA = 6,02 × 10²³ mol⁻¹)', '2,7 × 10¹⁹', ['2,69 × 10²²', '6,0 × 10²⁰', '2,7 × 10¹⁶'], '1 cm³ = 10⁻³ L; n = 10⁻³ / 22,4 ≈ 4,5 × 10⁻⁵ mol. Molekül sayısı 4,5 × 10⁻⁵ × 6,02 × 10²³ ≈ 2,7 × 10¹⁹ bulunur.'),
  ('Dumas yöntemiyle azot tayininde 0,28 g organik örnek yakılıyor ve normal koşullarda 22,4 mL N₂ gazı toplanıyor. Örnekte azotun kütlece yüzdesi kaçtır? (N = 14)', '10', ['5', '20', '28,0'], '22,4 mL = 0,001 mol N₂ = 0,028 g azot. 0,028 / 0,28 × 100 = %10\'dur.'),
  ('28 g azot gazından amonyak, ondan da nitrik asit üretiliyor. N₂ → NH₃ basamağında verim %50, NH₃ → HNO₃ basamağında verim %80\'dir. Elde edilen HNO₃ kaç gramdır? (N = 14, H = 1, O = 16)', '50,4', ['63', '31,5', '100,8'], '28 g N₂ = 1 mol = 2 mol N atomu. 2 × 0,50 × 0,80 = 0,8 mol HNO₃ elde edilir; kütle 0,8 × 63 = 50,4 g\'dır.'),
  ('NaHCO₃ ve NaCl içeren 10 g karışım ısıtıldığında yalnız NaHCO₃ ayrışıyor ve kütle 1,55 g azalıyor. Karışımda NaHCO₃ kütlece yüzde kaçtır? (NaHCO₃ = 84 g/mol; ayrışmada 168 g tuz 62 g kaybeder)', '42', ['15,5', '21', '84'], '62 g kayıp 168 g NaHCO₃\'e karşılık gelir; 1,55 g kayıp için 168 × 1,55 / 62 = 4,2 g NaHCO₃ vardır. Yüzde 4,2 / 10 × 100 = 42.'),
  ('6,2 g beyaz fosfor (P₄) ile 7,1 g klor gazı P₄ + 6Cl₂ → 4PCl₃ tepkimesine göre karıştırılıyor. Kuramsal olarak en çok kaç gram PCl₃ oluşur? (P = 31, Cl = 35,5)', '9,2', ['13,8', '6,9', '27,5'], '0,05 mol P₄ ve 0,1 mol Cl₂ vardır; Cl₂ sınırlayıcıdır. 0,1 × 4/6 = 0,0667 mol PCl₃ (137,5 g/mol) → 9,2 g.'),
  ('0,54 g alüminyum ile 7,62 g iyot, 2Al + 3I₂ → 2AlI₃ tepkimesiyle tepkimeye sokuluyor. Hangi sonuç doğrudur? (Al = 27, I = 127)', 'İkisi de tamamen harcanır ve 8,16 g AlI₃ oluşur.', ['Alüminyum artar ve 7,62 g AlI₃ oluşur.', 'İyot artar ve 4,08 g AlI₃ oluşur.', 'İkisi de tamamen harcanır ve 7,62 g AlI₃ oluşur.'], '0,54 / 27 = 0,02 mol Al ve 7,62 / 254 = 0,03 mol I₂ tam stokiyometrik orandadır (2 : 3). Oluşan AlI₃ kütlesi girenlerin toplamına eşittir: 8,16 g.'),
  ('CH₄ ve C₂H₆ gazlarından oluşan toplam 0,3 mol karışım tamamen yandığında 0,5 mol CO₂ oluşuyor. Karışımda kaç mol CH₄ vardır?', '0,1', ['0,2', '0,15', '0,25'], 'CH₄ x, C₂H₆ y mol olsun: x + y = 0,3 ve x + 2y = 0,5. Çözümle y = 0,2 ve x = 0,1 mol bulunur.'),
  ('Bakırın derişik sülfürik asitle tepkimesi Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O biçimindedir. İstenen ürün CuSO₄ ise atom ekonomisi yaklaşık yüzde kaçtır? (Cu = 64, S = 32, O = 16, H = 1)', '62', ['25', '50', '100'], 'Girenlerin kütlesi 64 + 196 = 260 g/mol, CuSO₄ ise 160 g/mol\'dür. 160 / 260 × 100 ≈ %62\'dir.'),
  ('Süperfosfat gübresi Ca₃(PO₄)₂ + 2H₂SO₄ → Ca(H₂PO₄)₂ + 2CaSO₄ tepkimesiyle üretilir. 31 g Ca₃(PO₄)₂ tam verimle dönüşürse kaç gram Ca(H₂PO₄)₂ oluşur? (Ca = 40, P = 31, O = 16, H = 1)', '23,4', ['46,80', '31', '11,7'], '31 / 310 = 0,1 mol Ca₃(PO₄)₂ 0,1 mol Ca(H₂PO₄)₂ verir. Mol kütlesi 234 g/mol; kütle 23,4 g\'dır.'),
  ('İyotlu tuz üretiminde 1 kg tuza yaklaşık 34 mg iyot (I = 127) sağlayacak miktarda KIO₃ (214 g/mol) katılıyor. Gerekli KIO₃ kütlesi yaklaşık kaç miligramdır?', '57,3', ['34', '28,00', '214'], '34 mg iyot 34/127 ≈ 0,268 mmol\'dür. Her KIO₃\'te bir I vardır; 0,268 × 214 ≈ 57,3 mg KIO₃ gerekir.'),
  ('Asit yağmuru mermer heykelleri CaCO₃ + H₂SO₄ → CaSO₄ + H₂O + CO₂ tepkimesiyle aşındırır. Saf CaCO₃\'ten yapılmış 10 kg\'lık bir parça tamamen CaSO₄\'e dönüşürse katı kütlesi kaç kg olur? (Ca = 40, S = 32, O = 16, C = 12)', '13,6', ['10,00', '7,4', '5,6'], '10 kg CaCO₃ = 10 000 g / 100 = 100 mol = 0,1 kmol; 0,1 kmol CaSO₄ kütlesi 0,1 × 136 = 13,6 kg\'dır. CO₂ ve su ayrılır, katı kütlesi artar.'),
  ('14,5 g sıva alçısı CaSO₄·½H₂O (145 g/mol), suyla karıştırılıp sertleşerek CaSO₄·2H₂O (172 g/mol) hâline geçiyor. Bu sırada kütle kaç gram artar?', '2,7', ['1,80', '3,6', '0,9'], '14,5 / 145 = 0,1 mol alçı; her mol 1,5 mol su bağlar. 0,15 mol × 18 = 2,7 g artış olur (14,5 + 2,7 = 17,2 g).'),
];
